// Create a controlled driver to test the multi-turn agent loop deterministically
class MockLoopDriver {
  id = 'mock-loop';
  name = 'Mock Loop Engine';
  type = 'local-daemon';
  endpoint = 'http://localhost';

  turn = 0;

  async checkAvailability() {
    return { online: true, state: 'ready' };
  }

  async discoverModels() {
    return [{
      id: 'mock-model',
      name: 'Mock Model',
      providerId: this.id,
      contextWindow: 4096,
      status: 'ready',
      supportsToolCalling: true,
      supportsStreaming: true
    }];
  }

  getCapabilities() {
    return { streaming: true, toolCalling: true, structuredOutput: true, embeddings: false };
  }

  async generate(options) {
    this.turn++;

    // Turn 1: Emit a tool call to write a file
    if (this.turn === 1) {
      return {
        content: 'Je vais créer le fichier de test.',
        toolCalls: [{
          id: 'call_test_001',
          toolId: 'filesystem',
          name: 'filesystem',
          arguments: {
            action: 'write',
            path: 'test_orchestrator_output.txt',
            content: 'Contenu généré par l’Orchestrator Evis sans simulation ni regex.'
          }
        }],
        finishReason: 'tool_calls'
      };
    }

    // Turn 2: Receive tool result and provide final synthesis
    return {
      content: 'Le fichier test_orchestrator_output.txt a été créé avec succès sur le disque physique.',
      finishReason: 'stop'
    };
  }
}

